test.query:
SELECT sum(jaroSimilarity(
    if(number % 2 = 0, repeat('AB', 32), repeat('BA', 32)),
    if(number % 2 = 0, repeat('BA', 32), repeat('AB', 32))))
FROM numbers(1000000) FORMAT Null

SELECT sum(jaroSimilarity(
    if(number % 2 = 0, concat(repeat('AB', 32), 'A'), concat(repeat('BA', 32), 'B')),
    if(number % 2 = 0, concat(repeat('BA', 32), 'B'), concat(repeat('AB', 32), 'A'))))
FROM numbers(500000) FORMAT Null

SELECT sum(jaroSimilarity(
    if(number % 2 = 0, repeat('XYZ', 86), repeat('ZYX', 86)),
    if(number % 2 = 0, repeat('ZYX', 86), repeat('XYZ', 86))))
FROM numbers(100000) FORMAT Null

SELECT sum(jaroWinklerSimilarity(
    if(number % 2 = 0, repeat('AB', 32), repeat('BA', 32)),
    if(number % 2 = 0, repeat('BA', 32), repeat('AB', 32))))
FROM numbers(1000000) FORMAT Null

SELECT sum(jaroWinklerSimilarity(
    if(number % 2 = 0, repeat('XYZ', 86), repeat('ZYX', 86)),
    if(number % 2 = 0, repeat('ZYX', 86), repeat('XYZ', 86))))
FROM numbers(100000) FORMAT Null
